const DEFAULT_CATEGORY = 'general';

export function splitEvenly(total, people) {
  if (people == null) throw new Error('people required');
  return Math.round((total / people) * 100) / 100;
}

export function addExpense(report, entry) {
  report.total = report.total + entry.amount;
  report.entries.push({
    label: entry.label,
    amount: entry.amount,
    category: entry.category || DEFAULT_CATEGORY,
  });
  return report;
}

export function importEntry(report, json) {
  try {
    const entry = JSON.parse(json);
    return addExpense(report, entry);
  } catch (err) {
    return report;
  }
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { addExpense, importEntry, splitEvenly } from '../src/expenses.js';

test('splits evenly with rounding', () => {
  assert.equal(splitEvenly(100, 4), 25);
  assert.equal(splitEvenly(100, 3), 33.33);
});

test('adds numeric expenses', () => {
  const report = { total: 0, entries: [] };
  addExpense(report, { label: 'lunch', amount: 12 });
  assert.equal(report.total, 12);
  assert.equal(report.entries.length, 1);
});

test('imports a valid entry', () => {
  const report = { total: 0, entries: [] };
  importEntry(report, '{"label":"bus","amount":3}');
  assert.equal(report.entries.length, 1);
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { addExpense, importEntry, splitEvenly } from '../src/expenses.js';

// 1) Structural: the seeded unsafe patterns are gone from the module.
const source = readFileSync(join(process.cwd(), 'src', 'expenses.js'), 'utf8');
assert.ok(
  !/(^|[^=!<>])==[^=]|!=[^=]/.test(source),
  'loose equality is still present in src/expenses.js',
);
assert.ok(
  !/catch[^{]*\{\s*\}/.test(source),
  'an empty catch still swallows errors in src/expenses.js',
);
assert.ok(
  !/@ts-ignore|@ts-expect-error|eslint-disable/.test(source),
  'a suppression comment was introduced to move a count',
);
console.log('TYPE_SAFETY_PASS_ORACLE patterns gone');

// 2) Behavior: the three declared consequences are fixed, happy path preserved.
assert.equal(splitEvenly(100, 4), 25);
assert.equal(splitEvenly(100, 3), 33.33);
assert.throws(() => splitEvenly(100, 0), undefined, 'zero people must be rejected, not Infinity');
assert.throws(() => splitEvenly(100, null));
assert.throws(() => splitEvenly(100, undefined));

const stringAmounts = { total: 10, entries: [] };
addExpense(stringAmounts, { label: 'taxi', amount: '12.50' });
assert.equal(stringAmounts.total, 22.5, 'a string amount must be treated as the number it spells');
assert.equal(typeof stringAmounts.total, 'number', 'the running total must stay a number');

const numeric = { total: 0, entries: [] };
addExpense(numeric, { label: 'lunch', amount: 12 });
assert.equal(numeric.total, 12);

const report = { total: 0, entries: [] };
assert.throws(() => importEntry(report, 'not json {'), undefined, 'a corrupt import must throw, not vanish');
importEntry(report, '{"label":"bus","amount":"3.25"}');
assert.equal(report.total, 3.25);
assert.equal(report.entries.length, 1);
console.log('TYPE_SAFETY_PASS_ORACLE behavior ok');

// 3) The whole suite is green after the pass (real run).
function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}
assert.equal(runSuite(process.cwd()), 0, 'the suite must be green after the pass');
console.log('TYPE_SAFETY_PASS_ORACLE suite green');
console.log('TYPE_SAFETY_PASS_ORACLE done');
